const appts = $input.all().map(function(i){ return i.json; }).filter(function(r){ return r.appointment_id; });
const existing = appts.find(function(a){ return a.appointment_id === 'appt_guided_demo_2'; });
if (existing) { return [{ json: { already_done: true, message: 'Milo already booked this patient a Check-up (via Ava) for ' + existing.start_time + '.', appointment_id: existing.appointment_id } }]; }
const start = new Date('2026-09-09T10:00:00.000Z');
const end = new Date(start.getTime() + 30 * 60000);
const providers = ['Dr. Adeyemi', 'Dr. Novak'];
const chairs = ['Chair 1', 'Chair 2'];
let provider = null, chair = null;
for (let p = 0; p < providers.length; p++) { for (let c = 0; c < chairs.length; c++) { const conflict = appts.some(function(a){ if (a.status === 'Cancelled') return false; const rs = new Date(a.start_time); const re = new Date(a.end_time); return start < re && end > rs && (a.provider === providers[p] || a.chair === chairs[c]); }); if (!conflict) { provider = providers[p]; chair = chairs[c]; break; } } if (provider) break; }
return [{ json: { already_done: false, start_time: start.toISOString(), end_time: end.toISOString(), provider: provider, chair: chair } }];

const rows = $input.all().map(function(i){ return i.json; }).filter(function(r){ return r.approval_id; });
const pending = rows.filter(function(r){ return r.status === 'Pending'; });
const ids = pending.map(function(r){ return r.approval_id; });
return [{ json: { step: 3, message: 'Luna has ' + pending.length + ' reminder/recall message(s) awaiting approval. Open the Approval Processor with one of these approval_ids to approve or reject.', changed_record_ids: JSON.stringify(ids), suggested_dashboard_section: 'Approvals', next_step: 4 } }];

const appts = $('Get Appointments (Step 8)').all().map(function(i){ return i.json; }).filter(function(r){ return r.appointment_id; });
const convos = $('Get Conversations (Step 8)').all().map(function(i){ return i.json; }).filter(function(r){ return r.conversation_id; });
const approvals = $('Get Approvals (Step 8)').all().map(function(i){ return i.json; }).filter(function(r){ return r.approval_id; });
const events = $('Get Activity Events (Step 8)').all().map(function(i){ return i.json; }).filter(function(r){ return r.event_id; });
const confirmed = appts.filter(function(a){ return a.status === 'Confirmed'; }).length;
const completed = appts.filter(function(a){ return a.status === 'Completed'; }).length;
const cancelled = appts.filter(function(a){ return a.status === 'Cancelled'; }).length;
const needsAttention = convos.filter(function(c){ return c.status === 'Needs attention'; }).length;
const staffHandling = convos.filter(function(c){ return c.status === 'Staff handling'; }).length;
const pending = approvals.filter(function(a){ return a.status === 'Pending'; }).length;
const slotsFilled = events.filter(function(e){ return e.type === 'waitlist.filled'; }).length;
const summary = 'Updated briefing: ' + confirmed + ' confirmed, ' + completed + ' completed, and ' + cancelled + ' cancelled appointment(s). ' + needsAttention + ' conversation(s) need attention and ' + staffHandling + ' are now staff-handled. ' + pending + ' approval(s) still pending. Finn has filled ' + slotsFilled + ' slot(s) from the waitlist this session.';
return [{ json: { step: 8, message: summary, changed_record_ids: '[]', suggested_dashboard_section: 'Overview', next_step: null } }];
